\n{\\u0022schema_id\\u0022:\\u0022agent-delivery.visible-session-controller.request.v1\\u0022,\\u0022request_id\\u0022:\\u0022RSW-C3\\u0022,\\u0022created_at\\u0022:\\u00222026-05-11T12:36:09Z\\u0022,\\u0022requested_by\\u0022:{\\u0022target_id\\u0022:\\u0022RSW-PARENT\\u0022,\\u0022role\\u0022:\\u0022parent\\u0022},\\u0022child\\u0022:{\\u0022target_id\\u0022:\\u0022RSW-C3\\u0022,\\u0022handoff_path\\u0022:\\u0022/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs/tests/docworkflow-agent-delivery/e2e/session-workflow-live/20260511T123609Z-md-e2e-5-controller-live/handoffs/rsw-c3-handoff.md\\u0022,\\u0022expected_output_path\\u0022:\\u0022/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs/tests/docworkflow-agent-delivery/e2e/session-workflow-live/20260511T123609Z-md-e2e-5-controller-live/target/output/count.txt\\u0022,\\u0022expected_output_text\\u0022:\\u00221\\\\n2\\\\n3\\\\n\\u0022},\\u0022launch\\u0022:{\\u0022agent\\u0022:\\u0022codex\\u0022,\\u0022adapter\\u0022:\\u0022codex-app-server\\u0022,\\u0022mode\\u0022:\\u0022launch\\u0022,\\u0022initiating_project_cwd\\u0022:\\u0022/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs\\u0022,\\u0022out\\u0022:\\u0022/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs/tests/docworkflow-agent-delivery/e2e/session-workflow-live/20260511T123609Z-md-e2e-5-controller-live/launches/children\\u0022}}\\n\\u0060\\u0060\\u0060\\n\\nWrite \\u0060controller/requests/RSW-C4.request.json\\u0060:\\n\\n\\u0060\\u0060\\u0060json\\n{\\u0022schema_id\\u0022:\\u0022agent-delivery.visible-session-controller.request.v1\\u0022,\\u0022request_id\\u0022:\\u0022RSW-C4\\u0022,\\u0022created_at\\u0022:\\u00222026-05-11T12:36:09Z\\u0022,\\u0022requested_by\\u0022:{\\u0022target_id\\u0022:\\u0022RSW-PARENT\\u0022,\\u0022role\\u0022:\\u0022parent\\u0022},\\u0022child\\u0022:{\\u0022target_id\\u0022:\\u0022RSW-C4\\u0022,\\u0022handoff_path\\u0022:\\u0022/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs/tests/docworkflow-agent-delivery/e2e/session-workflow-live/20260511T123609Z-md-e2e-5-controller-live/handoffs/rsw-c4-handoff.md\\u0022,\\u0022expected_output_path\\u0022:\\u0022/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs/tests/docworkflow-agent-delivery/e2e/session-workflow-live/20260511T123609Z-md-e2e-5-controller-live/target/output/count.txt\\u0022,\\u0022expected_output_text\\u0022:\\u00221\\\\n2\\\\n3\\\\n4\\\\n\\u0022},\\u0022launch\\u0022:{\\u0022agent\\u0022:\\u0022codex\\u0022,\\u0022adapter\\u0022:\\u0022codex-app-server\\u0022,\\u0022mode\\u0022:\\u0022launch\\u0022,\\u0022initiating_project_cwd\\u0022:\\u0022/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs\\u0022,\\u0022out\\u0022:\\u0022/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs/tests/docworkflow-agent-delivery/e2e/session-workflow-live/20260511T123609Z-md-e2e-5-controller-live/launches/children\\u0022}}\\n\\u0060\\u0060\\u0060\\n\\nWrite \\u0060controller/requests/RSW-C5.request.json\\u0060:\\n\\n\\u0060\\u0060\\u0060json\\n{\\u0022schema_id\\u0022:\\u0022agent-delivery.visible-session-controller.request.v1\\u0022,\\u0022request_id\\u0022:\\u0022RSW-C5\\u0022,\\u0022created_at\\u0022:\\u00222026-05-11T12:36:09Z\\u0022,\\u0022requested_by\\u0022:{\\u0022target_id\\u0022:\\u0022RSW-PARENT\\u0022,\\u0022role\\u0022:\\u0022parent\\u0022},\\u0022child\\u0022:{\\u0022target_id\\u0022:\\u0022RSW-C5\\u0022,\\u0022handoff_path\\u0022:\\u0022/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs/tests/docworkflow-agent-delivery/e2e/session-workflow-live/20260511T123609Z-md-e2e-5-controller-live/handoffs/rsw-c5-handoff.md\\u0022,\\u0022expected_output_path\\u0022:\\u0022/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs/tests/docworkflow-agent-delivery/e2e/session-workflow-live/20260511T123609Z-md-e2e-5-controller-live/target/output/count.txt\\u0022,\\u0022expected_output_text\\u0022:\\u00221\\\\n2\\\\n3\\\\n4\\\\n5\\\\n\\u0022},\\u0022launch\\u0022:{\\u0022agent\\u0022:\\u0022codex\\u0022,\\u0022adapter\\u0022:\\u0022codex-app-server\\u0022,\\u0022mode\\u0022:\\u0022launch\\u0022,\\u0022initiating_project_cwd\\u0022:\\u0022/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs\\u0022,\\u0022out\\u0022:\\u0022/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs/tests/docworkflow-agent-delivery/e2e/session-workflow-live/20260511T123609Z-md-e2e-5-controller-live/launches/children\\u0022}}\\n\\u0060\\u0060\\u0060\\n\\n## Completion Report\\n\\nReport only that the five request files were published and that no child launch command was run.\\n\u0022,\u0022exitCode\u0022:0,\u0022durationMs\u0022:0},\u0022threadId\u0022:\u0022019e170c-9e18-72d1-b44e-b88f30256f02\u0022,\u0022turnId\u0022:\u0022019e170c-9e9a-7f92-aeee-56260769e7ab\u0022,\u0022completedAtMs\u0022:1778503183996}}}\ntests/docworkflow-agent-delivery/e2e/session-workflow-live/20260511T123609Z-md-e2e-5-controller-live/launches/parent/20260511T123923Z-rsw-parent/app-server-transcript.jsonl:99:{\u0022at\u0022:\u00222026-05-11T12:39:43.9978080\\u002B00:00\u0022,\u0022direction\u0022:\u0022server\u0022,\u0022id\u0022:null,\u0022method\u0022:\u0022item/completed\u0022,\u0022message\u0022:{\u0022method\u0022:\u0022item/completed\u0022,\u0022params\u0022:{\u0022item\u0022:{\u0022type\u0022:\u0022commandExecution\u0022,\u0022id\u0022:\u0022call_PT8Yzhp1OxsjGwvU143Zkz17\u0022,\u0022command\u0022:\u0022/bin/zsh -lc \\u0022sed -n \\u00271,220p\\u0027 /Users/dh/Documents/DanielsVault/_shared/shared-ai-docs/skills-repo/skills/spec-change-delivery/SKILL.md\\u0022\u0022,\u0022cwd\u0022:\u0022/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs\u0022,\u0022processId\u0022:\u002219998\u0022,\u0022source\u0022:\u0022unifiedExecStartup\u0022,\u0022status\u0022:\u0022completed\u0022,\u0022commandActions\u0022:[{\u0022type\u0022:\u0022read\u0022,\u0022command\u0022:\u0022sed -n \\u00271,220p\\u0027 /Users/dh/Documents/DanielsVault/_shared/shared-ai-docs/skills-repo/skills/spec-change-delivery/SKILL.md\u0022,\u0022name\u0022:\u0022SKILL.md\u0022,\u0022path\u0022:\u0022/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs/skills-repo/skills/spec-change-delivery/SKILL.md\u0022}],\u0022aggregatedOutput\u0022:\u0022---\\nname: spec-change-delivery\\ndescription: Execute one bounded change from a spec or requirements document with strict scope control, optional OpenSpec usage, deterministic verification, and handoff-ready evidence. Use whenever the user asks to implement one spec item, ship one change change, apply a planned task, deliver a single requirement safely, or avoid scope creep and partial implementations. Works with or without OpenSpec.\\n---\\n\\n# spec-change-delivery\\n\\n## Use This Skill When\\n\\nUse this skill when the user wants **execution**, not more planning:\\n- \\u0022implement this spec item\\u0022\\n- \\u0022ship just this one change\\u0022\\n- \\u0022apply the next planned task\\u0022\\n- \\u0022do one safe change only\\u0022\\n- \\u0022avoid scope creep\\u0022\\n\\nDo **not** use this skill to write or refine the whole spec from scratch. For that, prefer \\u0060doc-coauthoring\\u0060 or \\u0060refine-plan\\u0060.\\n\\n## Core Promise\\n\\nDeliver exactly one bounded change from requirements to verified implementation.\\nPrioritize predictability: explicit scope, clear gates, runnable checks, and a final \\u0060READY\\u0060 / \\u0060NOT READY\\u0060 verdict.\\n\\n## Workflow Compatibility\\n\\nThis skill is the primary delivery path for **Workflow 2 (current)**:\\n- \\u0060spec -\\u003E spec-change-delivery -\\u003E (optional retro) -\\u003E (optional spec-closeout)\\u0060\\n\\n**Workflow 1 (legacy-compatible)** can continue without this skill:\\n- \\u0060spec -\\u003E refine-plan (iterative) -\\u003E direct-mode implementation -\\u003E (optional retro)\\u0060\\n\\nDo not force migration from Workflow 1 to Workflow 2 unless the user explicitly asks to switch.\\n\\n## Shared Delivery Gates\\n\\nUse \\u0060/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs/docs/doc-workflow.md\\u0060 as the canonical source for:\\n- **Definition of Ready (DoR)**\\n- **Definition of Done (DoD)**\\n- **Decision Freeze Pack**\\n- **Parallel Work Control Surface**\\n- **Mini-Retro**\\n\\nThis skill keeps short local definitions for convenience, but execution and the final \\u0060READY\\u0060 / \\u0060NOT READY\\u0060 verdict must stay aligned with the shared workflow document.\\n\\n## Key Terms\\n\\n- **Change**: the smallest self-contained increment that can be implemented and verified with one concrete done signal.\\n- **Scope contract**: a short agreement listing in scope, out of scope, acceptance targets, and planned verification before editing starts.\\n- **DoR (Definition of Ready)**: what must be true before implementation begins. See the shared workflow doc for the full gate.\\n- **DoD (Definition of Done)**: what evidence must exist before the change can be marked complete. See the shared workflow doc for the full gate.\\n- **OpenSpec mode**: use the repo\\u0027s OpenSpec workflow for proposal/tasks/spec deltas when the user asks for it or the repo already uses it.\\n- **Direct mode**: implement directly from the stated scope contract without creating a new OpenSpec change.\\n\\n## Required Inputs\\n\\n1. Target repository path.\\n2. One target spec/requirements artifact, or one clearly defined change request.\\n3. Execution mode: \\u0060openspec\\u0060 or \\u0060direct\\u0060.\\n   - Default to \\u0060direct\\u0060 for normal bounded specs unless the user explicitly wants OpenSpec or the repo already depends on it.\\n   - Default to \\u0060openspec\\u0060 for Parent/Child work created by the Spec Sizing Gate, unless the user explicitly chooses direct mode or the target repo has no useful OpenSpec context.\\n4. Verification commands or checks.\\n   - Use commands from the spec when present; otherwise derive the smallest safe set that proves the acceptance criteria.\\n\\n## If Inputs Are Missing\\n\\nBefore editing, make sure the minimum contract exists.\\nAsk the user if any of these are missing or ambiguous:\\n- which repo/path to change,\\n- which single requirement is in scope,\\n- what outcome counts as success,\\n- what environment or credentials are required.\\n\\nIf verification commands are missing, derive them explicitly and say what you chose.\\n\\n## Non-Negotiables\\n\\n1. One change per run.\\nDo not blend multiple independent changes in one pass.\\n2. Scope is explicit before editing.\\n3. Baseline, migration, and cutover are optional patterns, not defaults.\\nOnly include them when the spec explicitly requires them.\\n4. Do not silently descope acceptance criteria.\\n5. Do not claim done without fresh verification evidence.\\n6. Preserve behavior outside the change unless the spec requires a change.\\n7. If the spec provides explicit verification commands, execute all of them before final close-out.\\n8. Never silently skip verification commands from the spec.\\n9. If any required verification command cannot be run or fails, final verdict MUST be \\u0060NOT READY\\u0060.\\n10. Never present a verification as completed before the command has actually run and returned.\\n11. Never label a local rehearsal as an environment gate-run (\\u0060develop_hetzner\\u0060, production, etc.) unless executed in that actual target runtime.\\n12. When a spec distinguishes legacy vs candidate endpoints, assert and report both concrete values before execution (\\u0060OLD != CANDIDATE\\u0060).\\n13. If required spec checks depend on missing foundational runtime prerequisites (for example missing CLI, missing service repo, missing runtime manifests), stop early and ask for a scope decision before continuing.\\n14. Verification commands must be shell/platform explicit enough to run on the declared target operator environment (for example macOS vs Linux) without hidden behavior differences.\\n15. Verification commands must fail on assertion mismatches, not on benign pre-existing state (for example copying already-existing files).\\n16. If a scope guard compares branch history (\\u0060origin/develop...HEAD\\u0060), the spec must either require a dedicated clean branch or define a working-tree-only fallback guard for long-lived branches.\\n17. Runtime smoke checks after \\u0060docker compose up\\u0060 must include a deterministic readiness strategy (poll/retry/restart policy) before first HTTP assertions.\\n18. Before full verification execution, run a risk-based preflight only for high-failure-risk commands (runtime boot, TLS/bootstrap, branch-history guards, first endpoint smokes).\\n19. Preflight is preparation only: it must never be treated as a substitute for the required verification checklist.\\n20. Never recurse into \\u0022verification of verification\\u0022. One preflight pass is allowed; then run the canonical spec verification block.\\n21. If command simplifications are beneficial, propose them first with rationale and trade-offs; do not silently alter the spec command contract.\\n21a. If a required verification command fails because the command contract itself is stale or environment-fragile, do not silently replace it. Document the failed original command, synchronize the spec/child spec, Child Index/Handoff and OpenSpec/Evidence command list before treating any replacement as gate-relevant, then rerun the corrected command. If that sync is not in scope or requires a decision, stop with \\u0060NOT READY\\u0060.\\n22. For child-spec implementation, check parent/master conformance before editing when the parent path is known. If the child contradicts the parent or omits expected scope without re-entry, stop and route to \\u0060child-spec-hardening\\u0060.\\n23. If pre-implementation analysis finds a blocking content-quality flaw, stop before coding and route to \\u0060child-spec-hardening\\u0060. This includes requirements that are ambiguous, internally inconsistent, infeasible, untestable, incomplete for critical failure/edge cases, not traceable to the stated goal, or semantically broken in data/artifact/status contracts.\\n24. If a child spec lacks implementation-ready depth (normative contract, concrete harness/verification cases, hardened verification commands, DoR/DoD, parent conformance, and status/evidence provenance), stop before coding and route to \\u0060child-spec-hardening\\u0060.\\n25. For Parent/Child work, never implement a child spec without a documented Hardening Verdict of \\u0060IMPLEMENTATION READY\\u0060 or explicitly accepted \\u0060READY WITH NON-BLOCKING NOTES\\u0060. A plausible split, \\u0060ready_candidate\\u0060, section headings, or implicit reviewer confidence is not enough.\\n26. Before editing a child implementation, check the Child Index or Hardening Queue row when it exists. If it is missing, stale, contradicts the child verdict, lacks the exact full operational Child Index columns, uses renamed/merged substitute columns, lacks a \\u0060Session Handoff\\u0060 pointer, lacks evidence/OpenSpec pointers, lacks dependencies/write-set/verification/next-action detail, or names a different next action, stop and route to \\u0060spec-orchestrator\\u0060 or \\u0060child-spec-hardening\\u0060 for sync.\\n27. Before editing a child implementation, require an enforceable \\u0060Allowed Write-Set\\u0060 in the Child Index and handoff. If it is approximate or includes uncertain language such as \\u0060voraussichtlich\\u0060, \\u0060likely\\u0060, \\u0060probably\\u0060, \\u0060expected\\u0060, \\u0060TBD\\u0060, \\u0060as needed\\u0060, \\u0060related files\\u0060, or \\u0060etc.\\u0060, stop and route to \\u0060child-spec-hardening\\u0060.\\n28. If this run starts from a Child Session Handoff, verify its Target Repository / Working Directory, child spec, parent conformance, Child Index \\u0060Session Handoff\\u0060 pointer, evidence/OpenSpec pointers, and Hardening Verdict before treating it as the kickoff contract. Do not trust the handoff blindly; stale or unlinked handoffs block implementation.\\n28a. If this run starts from an Agent Delivery Handoff, also look for current Agent Delivery Session Launch/Queue Evidence under \\u0060_specs/agent-delivery-session-launches/\\u0060. Matching means the same Target-ID and same Handoff path in \\u0060launch-request.json\\u0060/\\u0060evidence.json\\u0060. Status \\u0060queued\\u0060 or \\u0060launched\\u0060 can support the fresh-session handoff claim; \\u0060manual_start_required\\u0060 is not an automated transition success, and \\u0060blocked\\u0060 or \\u0060failed\\u0060 block delivery until resolved.\\n29. If this run is one lane of parallel child-spec execution, edit only the lane\\u0027s allowed write-set. Treat shared/read-only files as read-only unless this run is explicitly the integration-owner run.\\n30. In Parent/Child workflows, implement exactly one implementation-ready child per run. Do not implement against the parent spec as a whole; the parent is the scope/control layer.\\n31. If the handoff lists temp Evidence as an accepted baseline or dependency for later children, either persist it to a stable workspace path during this run or record an explicit retained-evidence limitation for closeout. Do not make a later child depend silently on \\u0060/tmp\\u0060 or OS temp paths.\\n\\n## Risk-Based Verification Preflight\\n\\nUse a short preflight phase before the main verification run when command fragility risk is high.\\n\\n1. Select only high-risk commands for preflight.\\n2. Mark preflight outcomes separately (\\u0060pass\\u0060, \\u0060warn\\u0060, \\u0060fail\\u0060) from verification statuses.\\n3. If preflight exposes command-contract flaws, pause and propose explicit simplifications/fixes to the user before modifying commands.\\n4. Keep preflight bounded to one pass; do not create recursive loops.\\n5. After preflight, run the full spec verification block and report gate-relevant statuses (\\u0060planned\\u0060, \\u0060ran-target\\u0060, \\u0060ran-rehearsal\\u0060, \\u0060failed\\u0060, \\u0060blocked\\u0060).\\n\\nIf the user authorizes or the current integration-owner scope already permits a command-contract repair, update the relevant spec/Child Index/Handoff/OpenSpec command references before the replacement command counts as gate evidence. Keep the original failed command in evidence as a finding, not as a pass.\\n\\n## Verification Truth Contract\\n\\nUse exact status language for every verification item:\\n\\n- \\u0060planned\\u0060: not run yet.\\n- \\u0060ran-target\\u0060: executed in the required target runtime/environment.\\n- \\u0060ran-rehearsal\\u0060: executed only in local/simulated context.\\n- \\u0060failed\\u0060: executed and assertion failed.\\n- \\u0060blocked\\u0060: could not execute due to missing prerequisites.\\n\\nRules:\\n\\n1. \\u0060READY\\u0060 is only possible when all required spec checks are \\u0060ran-target\\u0060.\\n2. Any required check that is \\u0060ran-rehearsal\\u0060, \\u0060failed\\u0060, \\u0060blocked\\u0060, or still \\u0060planned\\u0060 forces \\u0060NOT READY\\u0060.\\n3. If a rehearsal is still useful, keep it, but label it explicitly as rehearsal and non-gate evidence.\\n4. If you discover environment mismatch after earlier claims, issue an explicit status correction immediately and downgrade verdict until re-verified.\\n\\n## Spec Status, History, SessionId\\n\\nWhen this skill is used with a spec artifact, update the spec metadata as work progresses:\\n\\n1. Set status to \\u0060\\uD83D\\uDFE0 Plan\\u0060 when the scope contract is locked (direct or OpenSpec mode).\\n2. Set status to \\u0060\\uD83D\\uDD35 Implemented\\u0060 only after implementation artifacts exist and required execution evidence is captured.\\n3. Preserve \\u0060Date\\u0060 and \\u0060Scope\\u0060 lines unless the user explicitly requests a scope/date correction.\\n4. Append one history row per status transition using \\u0060| Date | Author | Change |\\u0060 with a short sentence.\\n5. Keep \\u0060SessionId\\u0060 unchanged if present; add \\u0060SessionId: \\u003Csession-id\\u003E\\u0060 if missing.\\n\\n## Scope Pressure Guardrail\\n\\nWhen the requested scope is too large for one verifiable increment:\\n1. Flag the risk explicitly.\\n2. Apply the shared Spec Sizing Gate and route to Parent/Child orchestration instead of continuing as one delivery run.\\n3. Propose or create 2-5 smaller child changes.\\n4. For each change provide:\\n   - goal,\\n   - dependency boundary,\\n   - concrete done signal.\\n5. Recommend an execution order.\\n6. Hand off to \\u0060spec-orchestrator\\u0060 for child inventory, coverage, hardening queue, optional OpenSpec ledger, and session-ready child handoffs.\\n7. Implement only one child change in the current run after it is implementation-ready.\\n\\n## Parallel Child-Spec Execution Guardrail\\n\\nIf the user explicitly asks to run child specs in parallel, act as an orchestrator first:\\n\\n1. Create a Parallel Work Control Surface before delegating or editing:\\n   - child spec or work block,\\n   - lane mode, which is normally \\u0060implementation\\u0060 for this skill,\\n   - owner/agent,\\n   - allowed write-sets,\\n   - shared files/read-only files for the lane,\\n   - dependencies,\\n   - required verification commands,\\n   - integration owner,\\n   - integration order.\\n2. Allow parallel implementation only when write-sets are disjoint and each editing lane has an isolated branch/worktree/OpenSpec change or clearly separated files.\\n3. Assign one integration owner for shared control files such as parent spec, slice plan, child-spec index, backlog, shared helpers, shared contracts, or common verification scripts.\\n4. Do not let parallel lanes change common contracts independently. If a contract, schema, helper, harness, or shared verification command must change, promote that as its own serial prerequisite slice.\\n5. If write-sets overlap, or if shared files, dependencies, verification commands, integration owner, or merge/sync order are unclear, recommend serial execution even when multiple child specs exist.\\n6. After lane completion, the integration owner performs integration review, reruns cross-slice verification, updates parent coverage/index/backlog, and reports a single final \\u0060READY\\u0060 / \\u0060NOT READY\\u0060 verdict.\\n\\nIf these conditions are not met, recommend serial execution even when multiple child specs exist.\\n\\n## Kickoff Contract\\n\\nAt the start of execution, normalize the request into this short contract:\\n- **In scope**\\n- **Out of scope**\\n- **Acceptance targets**\\n- **Planned verification**\\n- **Open risks / assumptions**\\n\\nThis prevents drift and creates a clean handoff record.\\n\\n## Example Kickoff\\n\\nIf the user says, \\u0022Implement the retry-timeout requirement from the plan, nothing else,\\u0022 the kickoff should look like:\\n- **In scope**: retry/timeout behavior for the affected call path\\n- **Out of scope**: unrelated refactors, observability expansion, broader cleanup\\n- **Acceptance targets**: timeout is configurable, retry path works as specified\\n- **Planned verification**: targeted test(s) plus one affected-path smoke check\\n\\n## Delivery Workflow\\n\\n1. **Read and normalize scope**\\n   - Extract: in scope, out of scope, requirements, test cases, acceptance criteria, dependencies, decisions, open items.\\n   - Convert test cases into **DoR -\\u003E DoD** checkpoints.\\n   - For child specs, locate and verify the Hardening Verdict, Parent Scope Conformance, full operational Child Index/Hardening Queue row, Child Index \\u0060Session Handoff\\u0060 pointer, and persisted Child Session Handoff including Target Repository / Working Directory before any implementation edit.\\n   - Verify that the \\u0060Child\\u0060 value in the Child Index is the stable child id used by the handoff and delivery invocation, for example \\u0060S3\\u0060. Combined labels such as \\u0060S3 Content Bundle\\u0060 are stale for gate purposes unless the same exact id is intentionally used everywhere.\\n   - Verify that the Child Index row includes these exact column names for the target child: Parent Coverage, Readiness / Hardening Verdict, Session Handoff, OpenSpec / Ledger, Dependencies, Allowed Write-Set, Verification, Evidence / Closeout, Backlog / Re-entry, and Next Action.\\n   - Do not accept compressed or renamed substitute columns such as \\u0060Dependencies / Evidence\\u0060, \\u0060Allowed Next Mode\\u0060, \\u0060Implementation Gate\\u0060, or \\u0060Closeout Sync\\u0060 as satisfying the operational Child Index gate.\\n   - Verify that \\u0060Allowed Write-Set\\u0060 is enforceable and matches the handoff. Approximate write-sets or uncertain language such as \\u0060voraussichtlich\\u0060, \\u0060likely\\u0060, \\u0060probably\\u0060, \\u0060expected\\u0060, \\u0060TBD\\u0060, \\u0060as needed\\u0060, \\u0060related files\\u0060, or \\u0060etc.\\u0060 block implementation.\\n   - Before any implementation edit, run \\u0060/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs/skills-repo/tools/ValidateChildReadiness.cs\\u0060 from a neutral directory such as \\u0060/tmp\\u0060 with absolute \\u0060--index\\u0060 and \\u0060--handoff\\u0060 paths for the target child. If it fails or cannot run, stop with \\u0060NOT READY\\u0060.\\n   - If Agent Delivery Session Launch/Queue Evidence is present, verify that \\u0060target_id\\u0060, \\u0060handoff_path\\u0060, \\u0060agent.requested_provider\\u0060, \\u0060status\\u0060, \\u0060launch-request.json\\u0060, and \\u0060start-prompt.md\\u0060 describe this same delivery kickoff. If no matching evidence exists, proceed only as a manual handoff and do not claim an automated queue/launch. If matching evidence says \\u0060manual_start_required\\u0060, keep that manual residue visible; if it says \\u0060blocked\\u0060 or \\u0060failed\\u0060, stop with \\u0060NOT READY\\u0060.\\n   - Treat semantic-only \\u0060SessionId\\u0060 labels as insufficient future session proof. A handoff needs matching launch evidence, a real Codex session id plus \\u0060.codex/...jsonl\\u0060 log path, \\u0060manual_start_required\\u0060 evidence, or explicit \\u0060legacy_reconstructed\\u0060 source/date for historical pre-launcher transitions.\\n   - If the Hardening Verdict is absent, stale, weaker than \\u0060IMPLEMENTATION READY\\u0060/accepted \\u0060READY WITH NON-BLOCKING NOTES\\u0060, inconsistent with the Child Index, backed only by a partial/compressed/aliased index, missing a linked handoff, or contradicted by the handoff, stop with \\u0060NOT READY\\u0060 and hand back to \\u0060child-spec-hardening\\u0060 or \\u0060spec-orchestrator\\u0060.\\n\u0022,\u0022exitCode\u0022:0,\u0022durationMs\u0022:0},\u0022threadId\u0022:\u0022019e170c-9e18-72d1-b44e-b88f30256f02\u0022,\u0022turnId\u0022:\u0022019e170c-9e9a-7f92-aeee-56260769e7ab\u0022,\u0022completedAtMs\u0022:1778503183996}}}\ntests/docworkflow-agent-delivery/e2e/session-workflow-live/20260511T123609Z-md-e2e-5-controller-live/launches/parent/20260511T123923Z-rsw-parent/app-server-transcript.jsonl:101:{\u0022at\u0022:\u00222026-05-11T12:39:44.0003160\\u002B00:00\u0022,\u0022direction\u0022:\u0022server\u0022,\u0022id\u0022:null,\u0022method\u0022:\u0022item/completed\u0022,\u0022message\u0022:{\u0022method\u0022:\u0022item/completed\u0022,\u0022params\u0022:{\u0022item\u0022:{\u0022type\u0022:\u0022commandExecution\u0022,\u0022id\u0022:\u0022call_FJPxam2tnQVGIJDHmxkOPL7H\u0022,\u0022command\u0022:\u0022/bin/zsh -lc \\u0022sed -n \\u00271,260p\\u0027 openspec/changes/agent-delivery-md-e2e-5-external-controller-integration/specs/docworkflow-agent-delivery-testsuite/spec.md\\u0022\u0022,\u0022cwd\u0022:\u0022/Users/dh/Documents/DanielsVault/_shared/shared-ai-docs\u0022,\u0022processId\u0022:\u002268975\u0022,\u0022source\u0022:\u0022unifiedExecStartup\u0022,\u0022status\u0022:\u0022completed\u0022,\u0022commandActions\u0022:[{\u0022type\u0022:\u0022read\u0022,\u0022command\u0022:\u0022sed -